extern "C" void DirtyErrName(char* pBuffer, s32 iBufSize, u32 uError)
{
    u32 i;
    for (i = 0; i < 180; ++i)
    {
        if ((kDirtyErrors[i].uCode & 0x7fffffffu) == (uError & 0x7fffffffu))
        {
            ds_snzprintf(pBuffer, iBufSize, "%s/0x%08x", kDirtyErrors[i].pName, uError);
            return;
        }
    }
    for (i = 0; i < 180; ++i)
    {
        if ((kDirtyErrors[i].uCode & 0xffffu) == (uError & 0xffffu))
        {
            ds_snzprintf(pBuffer, iBufSize, "%s/0x%08x", kDirtyErrors[i].pName, uError);
            return;
        }
    }
    ds_snzprintf(pBuffer, iBufSize, "0x%08x", uError);
}

extern "C" const char* DirtyErrGetName(u32 uError)
{
    DirtyErrName(gDirtyErrName, sizeof(gDirtyErrName), uError);
    return gDirtyErrName;
}
